(function(){'use strict';Lampa.Lang.add({settings_player_custom_scheme:{ru:'URL-схема кастомного плеера',en:'Custom player URL scheme',uk:'URL-схема кастомного плеєра'},settings_player_custom_scheme_descr:{ru:'Введите URL-схему. Примеры: iina://weblink?url= или vlc://',en:'Enter URL scheme. Examples: iina://weblink?url= or vlc://',uk:'Введіть URL-схему. Приклади: iina://weblink?url= або vlc://'}});function startPlugin(){if(window.macos_players_plugin)return;window.macos_players_plugin=true;console.log('[macOS Players] v1.0.2 loaded');if(!Lampa.Platform.macOS()){console.log('[macOS Players] Not macOS');return}console.log('[macOS Players] macOS detected');try{Lampa.SettingsApi.addParam({component:'player',param:{name:'custom_player_scheme',type:'input',placeholder:'iina://weblink?url=',default:''},field:{name:Lampa.Lang.translate('settings_player_custom_scheme'),description:Lampa.Lang.translate('settings_player_custom_scheme_descr')}});console.log('[macOS Players] Settings added')}catch(e){console.error('[macOS Players] Settings error:',e)}var originalPlay=Lampa.Player.play;if(!originalPlay){console.warn('[macOS Players] Player.play not found');return}Lampa.Player.play=function(data){data=data||{};var playerType='player';if(data.torrent_hash)playerType='player_torrent';else if(data.iptv)playerType='player_iptv';var selectedPlayer=Lampa.Storage.field(playerType)||'inner';console.log('[macOS Players] Player:',selectedPlayer);if(selectedPlayer==='movist'||selectedPlayer==='custom'){handleExternalPlayer(data,selectedPlayer);return}return originalPlay.apply(this,arguments)};console.log('[macOS Players] Hooked');function handleExternalPlayer(data,playerType){console.log('[macOS Players] Launch:',playerType);var url=data.url;if(!url){console.error('[macOS Players] No URL');Lampa.Noty.show('No video URL');return}url=url.replace('&preload','&play');var encodedUrl=encodeURIComponent(url);var externalUrl='';if(playerType==='movist'){externalUrl='movist://open?url='+encodedUrl}else if(playerType==='custom'){var scheme=Lampa.Storage.field('custom_player_scheme')||'';if(!scheme){Lampa.Noty.show('Configure custom scheme in settings');return}if(scheme.indexOf('${url}')>-1){externalUrl=scheme.replace('${url}',encodedUrl)}else if(scheme.indexOf('${_url}')>-1){externalUrl=scheme.replace('${_url}',encodeURI(url))}else if(scheme.indexOf('${furl}')>-1){externalUrl=scheme.replace('${furl}',url)}else{externalUrl=scheme+encodedUrl}}if(externalUrl){console.log('[macOS Players] Opening:',externalUrl);try{window.location.assign(externalUrl);Lampa.Noty.show('Opening '+playerType)}catch(e){console.error('[macOS Players] Error:',e);Lampa.Noty.show('Failed to launch')}}}console.log('[macOS Players] Initialized')}if(window.appready){startPlugin()}else{Lampa.Listener.follow('app',function(e){if(e.type==='ready')startPlugin()})}})();